lemma stepVec_ofFn {T : List ℕ} {a : ℕ} {w u : Fin a → ℕ}
    (h : ∀ i, T.getD (w i) 0 = u i + 1) :
    stepVec T (List.ofFn w) = Matrix.vecToNat u + 1

lemma stepVecT_ofFn {n a : ℕ} {w u : Fin a → ℕ}
    (h : ∀ i, encode (decode (w i) : Option (Semiterm L ξ n)) = u i + 1) :
    stepVecT (L := L) (ξ := ξ) n (List.ofFn w) = Matrix.vecToNat u + 1

private lemma map_subst_eq_free (φ : Semiproposition L 1) (h : ¬φ.FVar? m) :
    (@Rew.rewriteMap L ℕ ℕ 0 (fun x ↦ if x = m then 0 else x + 1)) ▹
      (φ/[&m] : Proposition L) = Rewriting.free φ

private lemma map_rewriteMap_eq_shifts (Δ : Sequent L) (h : ∀ φ ∈ Δ, ¬φ.FVar? m) :
    Δ.map (fun φ ↦ @Rew.rewriteMap L ℕ ℕ 0
      (fun x ↦ if x = m then 0 else x + 1) ▹ φ) = Δ⁺

lemma exsVec {k l} {P : (Fin k → M) → (Fin l → M) → Prop}
    (h : L.Definable fun w : Fin (k + l) → M ↦ P (fun i ↦ w (i.castAdd l)) (fun j ↦ w (j.natAdd k))) :
    L.Definable fun v : Fin k → M ↦ ∃ ys : Fin l → M, P v ys

lemma allVec {k l} {P : (Fin k → M) → (Fin l → M) → Prop}
    (h : L.Definable fun w : Fin (k + l) → M ↦ P (fun i ↦ w (i.castAdd l)) (fun j ↦ w (j.natAdd k))) :
    L.Definable fun v : Fin k → M ↦ ∀ ys : Fin l → M, P v ys

lemma substitution {P : (Fin k → M) → Prop} {f : Fin k → (Fin l → M) → M}
    (hP : L.Definable P) (hf : ∀ i, L.DefinableFunction (f i)) :
    L.Definable fun z ↦ P (f · z)

lemma DefinablePred.comp {P : M → Prop} {k} {f : (Fin k → M) → M}
    [hP : L.DefinablePred P] (hf : L.DefinableFunction f) :
    L.Definable (fun v ↦ P (f v))

lemma substitution {f : Fin k → (Fin l → M) → M}
    (hF : L.DefinableFunction F) (hf : ∀ i, L.DefinableFunction (f i)) :
    L.DefinableFunction fun z ↦ F (fun i ↦ f i z)

lemma DefinableFunction₁.comp {k} {F : M → M} {f : (Fin k → M) → M}
    [hF : L.DefinableFunction₁ F] (hf : L.DefinableFunction f) :
    L.DefinableFunction (fun v ↦ F (f v))

private lemma eval_collectionMotive [V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻] (a : V) (v : Fin 1 → V) :
    (collectionMotive e θ a).Eval v id ↔
      ∃ w, ∀ x < v 0, x < a → ∃ u ≤ w, V ⊧/(u :> x :> e) θ

proof:
:= by
  rw [hb];
  have hswap : ∀ z : V,
      V ⊧/(z :> x :> w :> e) (φ.sigmaInv.rew (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ)))).val ↔
        V ⊧/(z :> x :> e) φ.sigmaInv.val := by
    intro z;
    rw [val_rew, Semiformula.eval_rew];
    have hA : (Semiterm.val (L := ℒₒᵣ) (M := V) (z :> x :> w :> e) Empty.elim) ∘
        (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ))) ∘ Semiterm.bvar
        = (z :> x :> e : Fin (n + 2) → V) := by
      funext i;
      cases i using Fin.cases with
      | zero => simp;
      | succ i =>
        cases i using Fin.cases with
        | zero => simp;
        | succ i => simp;
    have hB : (Semiterm.val (L := ℒₒᵣ) (M := V) (z :> x :> w :> e) Empty.elim) ∘
        (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ))) ∘ Semiterm.fvar
        = (Empty.elim : Empty → V) := by
      funext i; exact i.elim;
    rw [hA, hB];
  have hval : (‘#1 + 1’ : ArithmeticSemiterm Empty (n + 2)).valb (x :> w :> e) = w + 1 := by simp;
  rw [hval];
  simp only [hswap, Arithmetic.lt_succ_iff_le];

:= mod_ISigma_of_le (n₂ := s + 1) (by omega);
    have : V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻ := mod_paMinus_of_ISigma (n := s + 1);
    have iha : ∀ {m : ℕ} (u : ArithmeticSemiterm Empty m) (φ : Prenex 𝚷 s Empty (m + 1))
        (e : Fin m → V), V ⊧/e (∀'[u] φ).val ↔ ∀ x < u.valb e, V ⊧/(x :> e) φ.val :=
      fun u φ e => models_ball u φ e;
    have ihb : ∀ {m : ℕ} (u : ArithmeticSemiterm Empty m) (φ : Prenex 𝚷 s Empty (m + 1))
        (e : Fin m → V), V ⊧/e (∃'[u] φ).val ↔ ∃ x < u.valb e, V ⊧/(x :> e) φ.val :=
      fun u φ e => models_bexs u φ e;
    rw [ball_succ_sigma (u := u) (φ := φ), models_sigma];
    simp only [iha (Rew.bShift u), Semiterm.val_bShift, models_bexs_witness ihb φ,
      models_sigmaInv φ];
    constructor;
    . rintro ⟨w, hw⟩ x hx;
      obtain ⟨y, -, hy⟩ := hw x hx;
      exact ⟨y, hy⟩;
    . intro h;
      have hθ : Hierarchy 𝚺 (s + 1) φ.sigmaInv.val := φ.sigmaInv.val_hierarchy.accum 𝚺;
      exact sigma_exists_bound_witness hθ e (u.valb e) h;
  | 𝚷, s + 1, _, _, u, φ, e => by
    have ih : ∀ {m : ℕ} (u : ArithmeticSemiterm Empty m) (φ : Prenex 𝚺 (s + 1) Empty (m + 1))
        (e : Fin m → V), V ⊧/e (∃'[u] φ).val ↔ ∃ x < u.valb e, V ⊧/(x :> e) φ.val :=
      fun u φ e => models_bexs u φ e;
    have hthis : V ⊧/e (∃'[u] ∼φ).val ↔ ∃ x < u.valb e, V ⊧/(x :> e) (∼φ).val := ih u (∼φ) e;
    have hval : (∀'[u] φ).val = ∼(∃'[u] ∼φ).val := by
      rw [ball_succ_pi (u := u) (φ := φ)];
      exact val_neg (∃'[u] ∼φ);
    rw [hval];
    simp only [val_neg, LogicalConnective.HomClass.map_neg, LogicalConnective.Prop.neg_eq]
      at hthis ⊢;
    grind;

:= mod_ISigma_of_le (n₂ := s + 1) (by omega);
    have ih : ∀ {m : ℕ} (u : ArithmeticSemiterm Empty m) (φ : Prenex 𝚷 s Empty (m + 1))
        (e : Fin m → V), V ⊧/e (∃'[u] φ).val ↔ ∃ x < u.valb e, V ⊧/(x :> e) φ.val :=
      fun u φ e => models_bexs u φ e;
    set φ₁' := φ.sigmaInv;
    set φ₁ := φ₁'.val;
    set v := #1 :> #0 :> fun i => #(i.succ.succ) with hv;
    let φ₂' := φ₁'.rew (Rew.subst v);
    have hswap : ∀ (x b : V), V ⊧/(x :> b :> e) φ₂'.val ↔ V ⊧/(b :> x :> e) φ₁ := by
      intro x b;
      rw [val_rew, Semiformula.eval_rew];
      have hA : (Semiterm.val (M := V) (x :> b :> e) Empty.elim) ∘ (Rew.subst v) ∘ Semiterm.bvar
          = (b :> x :> e : Fin (n + 2) → V) := by
        funext i;
        cases i using Fin.cases with
        | zero => simp [hv];
        | succ i =>
          cases i using Fin.cases with
          | zero => simp [hv];
          | succ i => simp [hv];
      have hB : (Semiterm.val (M := V) (x :> b :> e) Empty.elim) ∘ (Rew.subst v) ∘ Semiterm.fvar
          = (Empty.elim : Empty → V) := by
        funext i; exact i.elim;
      rw [hA, hB];
    rw [bexs_succ_sigma (u := u) (φ := φ), val_sigma]
    show (∃ b, V ⊧/(b :> e) (∃'[Rew.bShift u] φ₂').val) ↔ ∃ x < u.valb e, V ⊧/(x :> e) φ.val;
    simp only [ih (Rew.bShift u) φ₂', Semiterm.val_bShift, hswap, models_sigmaInv φ];
    grind;
  | 𝚷, s + 1, _, _, u, φ, e => by
    have ih : ∀ {m : ℕ} (u : ArithmeticSemiterm Empty m) (φ : Prenex 𝚺 (s + 1) Empty (m + 1))
        (e : Fin m → V), V ⊧/e (∀'[u] φ).val ↔ ∀ x < u.valb e, V ⊧/(x :> e) φ.val :=
      fun u φ e => models_ball u φ e;
    have hthis : V ⊧/e (∀'[u] ∼φ).val ↔ ∀ x < u.valb e, V ⊧/(x :> e) (∼φ).val := ih u (∼φ) e;
    have hval : (∃'[u] φ).val = ∼(∀'[u] ∼φ).val := by
      rw [bexs_succ_pi (u := u) (φ := φ)];
      exact val_neg (∀'[u] ∼φ);
    rw [hval];
    simp only [val_neg, LogicalConnective.HomClass.map_neg, LogicalConnective.Prop.neg_eq]
      at hthis ⊢;
    grind;

:= mod_ISigma_of_le (n₂ := s + 1) (by omega);
    have : V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻ := mod_paMinus_of_ISigma (n := s);
    have iha : ∀ {m : ℕ} (φ ψ : Prenex 𝚷 s Empty m) (e : Fin m → V),
        V ⊧/e (φ ⋏ ψ).val ↔ V ⊧/e φ.val ∧ V ⊧/e ψ.val :=
      fun φ ψ e => models_and φ ψ e;
    rw [and_succ_sigma (φ := φ) (ψ := ψ), models_sigma];
    set φ₂' := φ.sigmaInv.rew (Rew.subst (#0 :> (#·.succ.succ)));
    set ψ₂' := ψ.sigmaInv.rew (Rew.subst (#0 :> (#·.succ.succ)));
    have hα_eval : ∀ z : V,
        V ⊧/(z :> e) (∃'[‘#0 + 1’] φ₂').val ↔ ∃ x ≤ z, V ⊧/(x :> e) φ.sigmaInv.val := by
      intro z;
      rw [models_bexs ‘#0 + 1’ φ₂' (z :> e)];
      simp only [φ₂', val_rew, Semiformula.eval_insert1];
      simp [Arithmetic.lt_succ_iff_le];
    have hβ_eval : ∀ z : V,
        V ⊧/(z :> e) (∃'[‘#0 + 1’] ψ₂').val ↔ ∃ x ≤ z, V ⊧/(x :> e) ψ.sigmaInv.val := by
      intro z;
      rw [models_bexs ‘#0 + 1’ ψ₂' (z :> e)];
      simp only [ψ₂', val_rew, Semiformula.eval_insert1];
      simp [Arithmetic.lt_succ_iff_le];
    simp only [iha (∃'[‘#0 + 1’] φ₂') (∃'[‘#0 + 1’] ψ₂'), models_sigmaInv φ, models_sigmaInv ψ,
      hα_eval, hβ_eval];
    constructor;
    . rintro ⟨z, ⟨x, -, hx⟩, ⟨y, -, hy⟩⟩;
      exact ⟨⟨x, hx⟩, ⟨y, hy⟩⟩;
    . rintro ⟨⟨x, hx⟩, ⟨y, hy⟩⟩;
      exact ⟨max x y, ⟨x, le_max_left x y, hx⟩, ⟨y, le_max_right x y, hy⟩⟩;
  | 𝚷, s + 1, _, _, φ, ψ, e => by
    have ih : ∀ {m : ℕ} (φ ψ : Prenex 𝚺 (s + 1) Empty m) (e : Fin m → V),
        V ⊧/e (φ ⋎ ψ).val ↔ V ⊧/e φ.val ∨ V ⊧/e ψ.val :=
      fun φ ψ e => models_or φ ψ e;
    have hthis : V ⊧/e (∼φ ⋎ ∼ψ).val ↔ V ⊧/e (∼φ).val ∨ V ⊧/e (∼ψ).val := ih (∼φ) (∼ψ) e;
    have hval : (φ ⋏ ψ).val = ∼(∼φ ⋎ ∼ψ).val := by
      rw [and_succ_pi (φ := φ) (ψ := ψ)];
      exact val_neg (∼φ ⋎ ∼ψ);
    rw [hval];
    simp only [val_neg, LogicalConnective.HomClass.map_neg, LogicalConnective.Prop.neg_eq]
      at hthis ⊢;
    grind;

:= mod_ISigma_of_le (n₂ := s + 1) (by omega);
    have ih : ∀ {m : ℕ} (φ ψ : Prenex 𝚷 s Empty m) (e : Fin m → V),
        V ⊧/e (φ ⋎ ψ).val ↔ V ⊧/e φ.val ∨ V ⊧/e ψ.val :=
      fun φ ψ e => models_or φ ψ e;
    rw [or_succ_sigma (φ := φ) (ψ := ψ), models_sigma];
    simp only [ih φ.sigmaInv ψ.sigmaInv, models_sigmaInv φ, models_sigmaInv ψ];
    exact exists_or;
  | 𝚷, s + 1, _, _, φ, ψ, e => by
    have ih : ∀ {m : ℕ} (φ ψ : Prenex 𝚺 (s + 1) Empty m) (e : Fin m → V),
        V ⊧/e (φ ⋏ ψ).val ↔ V ⊧/e φ.val ∧ V ⊧/e ψ.val :=
      fun φ ψ e => models_and φ ψ e;
    have hthis : V ⊧/e (∼φ ⋏ ∼ψ).val ↔ V ⊧/e (∼φ).val ∧ V ⊧/e (∼ψ).val := ih (∼φ) (∼ψ) e;
    have hval : (φ ⋎ ψ).val = ∼(∼φ ⋏ ∼ψ).val := by
      rw [or_succ_pi (φ := φ) (ψ := ψ)];
      exact val_neg (∼φ ⋏ ∼ψ);
    rw [hval];
    simp only [val_neg, LogicalConnective.HomClass.map_neg, LogicalConnective.Prop.neg_eq]
      at hthis ⊢;
    grind;

:= by
  have : V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻ := mod_paMinus_of_ISigma (n := s);
  show V ⊧/e
      (∃'[‘#0 + 1’] (∃'[‘#1 + 1’]
        (φ.sigmaInv.rew (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ)))))).sigma.val ↔
    ∃ x, V ⊧/(x :> e) φ.val;
  rw [models_sigma];
  have hβeval : ∀ z : V,
      V ⊧/(z :> e)
        (∃'[‘#0 + 1’] (∃'[‘#1 + 1’]
          (φ.sigmaInv.rew (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ)))))).val ↔
        ∃ y ≤ z, V ⊧/(y :> z :> e)
          (∃'[‘#1 + 1’] (φ.sigmaInv.rew (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ))))).val := by
    intro z;
    rw [models_bexs];
    have hval : (‘#0 + 1’ : ArithmeticSemiterm Empty (n + 1)).valb (z :> e) = z + 1 := by simp;
    rw [hval];
    simp only [Arithmetic.lt_succ_iff_le];
  have hαeval : ∀ y z : V,
      V ⊧/(y :> z :> e)
        (∃'[‘#1 + 1’] (φ.sigmaInv.rew (Rew.subst (#0 :> #1 :> (#·.succ.succ.succ))))).val ↔
        ∃ x ≤ z, V ⊧/(x :> y :> e) φ.sigmaInv.val :=
    fun y z => models_bexs_witness models_bexs φ y z e;
  simp only [hβeval, hαeval, models_sigmaInv φ];
  constructor;
  . rintro ⟨z, y, -, x, -, hx⟩;
    exact ⟨y, x, hx⟩;
  . rintro ⟨y, x, hx⟩;
    exact ⟨max x y, y, le_max_right x y, x, le_max_left x y, hx⟩;

:= by
  have hthis : V ⊧/e (∃' ∼φ).val ↔ ∃ x, V ⊧/(x :> e) (∼φ).val := models_exs (∼φ) e;
  have hval : (∀' φ).val = ∼(∃' ∼φ).val := by
    unfold all;
    exact val_neg (∃' ∼φ);
  rw [hval];
  simp only [val_neg, LogicalConnective.HomClass.map_neg, LogicalConnective.Prop.neg_eq] at hthis ⊢;
  grind;

:= by
  induction h with
  | verum Γ s n =>
    use verum;
    intro V _ _ e;
    exact (models_verum e).symm;
  | falsum Γ s n =>
    use falsum;
    intro V _ _ e;
    exact (models_falsum e).symm;
  | rel Γ s r v =>
    use rel r v;
    intro V _ _ e;
    exact (models_rel r v e).symm;
  | nrel Γ s r v =>
    use nrel r v;
    intro V _ _ e;
    exact (models_nrel r v e).symm;
  | and _ _ ihφ ihψ =>
    obtain ⟨φ', hφ'⟩ := ihφ;
    obtain ⟨ψ', hψ'⟩ := ihψ;
    use φ' ⋏ ψ';
    intro V _ _ e;
    rw [models_and φ' ψ' e];
    simp only [LogicalConnective.HomClass.map_and, LogicalConnective.Prop.and_eq];
    exact and_congr (hφ' V e) (hψ' V e);
  | or _ _ ihφ ihψ =>
    obtain ⟨φ', hφ'⟩ := ihφ;
    obtain ⟨ψ', hψ'⟩ := ihψ;
    use φ' ⋎ ψ';
    intro V _ _ e;
    rw [models_or φ' ψ' e];
    simp only [LogicalConnective.HomClass.map_or, LogicalConnective.Prop.or_eq];
    exact or_congr (hφ' V e) (hψ' V e);
  | ball pos _ ih =>
    obtain ⟨u, rfl⟩ := Rew.positive_iff.mp pos;
    obtain ⟨φ', hφ'⟩ := ih;
    use ∀'[u] φ';
    intro V _ _ e;
    rw [models_ball u φ' e];
    simp only [Semiformula.eval_ball];
    exact forall_congr' fun x => (imp_congr Iff.rfl (hφ' V (x :> e))).trans (by simp);
  | bexs pos _ ih =>
    obtain ⟨u, rfl⟩ := Rew.positive_iff.mp pos;
    obtain ⟨φ', hφ'⟩ := ih;
    use ∃'[u] φ';
    intro V _ _ e;
    rw [models_bexs u φ' e];
    simp only [Semiformula.eval_bexs];
    exact exists_congr fun x => (and_congr Iff.rfl (hφ' V (x :> e))).trans (by simp);
  | @exs s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use ∃' φ';
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (n₂ := s + 1) (by omega);
    rw [models_exs φ' e, Semiformula.eval_ex];
    exact exists_congr fun x => hφ' V (x :> e);
  | @all s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use ∀' φ';
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (n₂ := s + 1) (by omega);
    rw [models_all φ' e, Semiformula.eval_all];
    exact forall_congr' fun x => hφ' V (x :> e);
  | @sigma s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use φ'.sigma;
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (n₂ := s + 1) (by omega);
    rw [models_sigma φ' e, Semiformula.eval_ex];
    exact exists_congr fun x => hφ' V (x :> e);
  | @pi s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use φ'.pi;
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (n₂ := s + 1) (by omega);
    rw [models_pi φ' e, Semiformula.eval_all];
    exact forall_congr' fun x => hφ' V (x :> e);
  | @dummy_sigma s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use (∀' φ').altUp;
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (show s ≤ s + 1 + 1 by omega);
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 (s + 1) := mod_ISigma_of_le (show s + 1 ≤ s + 1 + 1 by omega);
    exact Semiformula.eval_all.trans
      ((forall_congr' fun x => hφ' V (x :> e)).trans
        ((models_all φ' e).symm.trans (models_altUp (∀' φ') e).symm));
  | @dummy_pi s n φ _ ih =>
    obtain ⟨φ', hφ'⟩ := ih;
    use (∃' φ').altUp;
    intro V _ _ e;
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := mod_ISigma_of_le (show s ≤ s + 1 + 1 by omega);
    have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 (s + 1) := mod_ISigma_of_le (show s + 1 ≤ s + 1 + 1 by omega);
    exact Semiformula.eval_ex.trans
      ((exists_congr fun x => hφ' V (x :> e)).trans
        ((models_exs φ' e).symm.trans (models_altUp (∃' φ') e).symm));

:= by
  have : 𝗘𝗤 ℒₒᵣ ⪯ T := eq_weakerThan_of_ISigma (s := s);
  obtain ⟨φ', hφ'⟩ := Prenex.models_exists_prenex h;
  use φ';
  apply provable_iff_of_models_iff;
  intro V _ _ e;
  have : V↓[ℒₒᵣ] ⊧* 𝗜𝚺 s := models_of_subtheory (T := 𝗜𝚺 s) (U := T) (inferInstance);
  exact hφ' V e;

:= by
  obtain ⟨_, hφ'⟩ := exists_prenex_of_hierarchy T h;
  exact ⟨_, by simpa [Prenex.val] using hφ'⟩;

statement:
lemma measured_bounded_sigma1_order_induction {m : V → V} {f : V → V} {P : V → Prop}
    (hm : 𝚺₁-Function₁ m) (hf : 𝚺₁-Function₁ f) (hP : 𝚺₁-Predicate P)
    (H : ∀ a, (∀ b ≤ f a, m b < m a → P b) → P a) : ∀ a, P a

proof:
:= by
  obtain ⟨φ, rfl⟩ := Quotient.exists_rep φ;
  obtain ⟨ψ, rfl⟩ := Quotient.exists_rep ψ;
  have h₁ : 𝓢 ⊢ φ 🡒 ψ := le_def _ |>.mp $ le_of_lt h;
  have h₂ : 𝓢 ⊬  ψ 🡒 φ := le_def _ |>.not.mp $ not_le_of_gt h;
  obtain ⟨ρ, hρ⟩ := incomplete_def.mp $ @hE (∼φ ⋏ ψ) $ by
    apply consistent_iff_exists_unprovable.mpr;
    use ⊥;
    apply deduction_iff.not.mpr;
    contrapose! h₂;
    cl_prover [h₂];
  use ⟦φ ⋎ (ψ ⋏ ∼ρ)⟧;
  refine ⟨⟨?_, ?_⟩, ⟨?_, ?_⟩⟩;
  . apply le_def _ |>.mpr;
    cl_prover;
  . apply le_def _ |>.not.mpr;
    by_contra! hC;
    apply hρ.1;
    apply deduction_iff.mpr;
    cl_prover [h₁, hC];
  . apply le_def _ |>.mpr;
    cl_prover [h₁];
  . apply le_def _ |>.not.mpr;
    by_contra hC;
    apply hρ.2;
    apply deduction_iff.mpr;
    cl_prover [h₁, hC];

:= by
  let φ := codeOfREPred P;
  use φ;
  have hP : P = { n : ℕ | T ⊢ φ/[n] } := Set.ext fun x ↦ rePred_weak_representation hRE;
  have ⟨d, hd⟩ : ∃ d : ℕ, ¬(¬P d ↔ T ⊢ ∼φ/[d]) := by
    by_contra h;
    apply hC;
    apply ComputablePred.computable_iff_re_compl_re.mpr;
    constructor;
    . assumption;
    . suffices REPred fun a : ℕ ↦ T ⊬ φ/[a] by simpa [hP] using! this;
      have : 𝚺₁-Predicate fun b : ℕ ↦ Bootstrapping.Provable T (Bootstrapping.neg ℒₒᵣ <| Bootstrapping.subst ℒₒᵣ ?[Bootstrapping.Arithmetic.numeral b] ⌜φ⌝) := by clear hP; definability;
      apply REPred.of_eq (rePred_iff_sigma1.mpr this);
      intro a;
      push Not at h;
      apply Iff.trans ?_ $ show T ⊢ ∼φ/[a] ↔ ¬T ⊢ φ/[a] by simpa [hP] using! h a |>.symm;
      constructor;
      . rintro hP
        apply Bootstrapping.Provable.sound
        simpa [Sentence.quote_def, Semiformula.quote_def, Rewriting.emb_subst_eq_subst_coe₁] using hP;
      . rintro hφ
        simpa [Sentence.quote_def, Semiformula.quote_def, Rewriting.emb_subst_eq_subst_coe₁] using
          Bootstrapping.internalize_provability (V := ℕ) hφ;
  push Not at hd;
  rcases hd with (⟨hd₁, hd₂⟩ | ⟨hd₁, hd₂⟩);
  . use d;
    constructor;
    . simpa [hP] using! hd₁;
    . simpa;
  . exfalso;
    apply Entailment.Consistent.not_bot (𝓢 := T);
    replace hd₁ : T ⊢ φ/[d] := by simpa [hP] using! hd₁;
    cl_prover [hd₁, hd₂];

:= by
  obtain ⟨φ, a, hφ₁, hφ₂⟩ := incomplete_of_REPred_not_ComputablePred_Nat' T hRE hC;
  apply incomplete_def.mpr;
  use φ/[⌜a⌝];
  constructor <;> assumption;

:= by
  apply Entailment.E_trans;
  . exact def_restrictedGödel;
  . exact Entailment.E_symm $ def_restrictedGödel';

:= by
  apply Semantics.models_iff.mp;
  apply models_of_provable (T := 𝗜𝚺₁) inferInstance;
  apply provable_E_restrictedGödel_restrictedGödel';

:= by
  apply Iff.trans $ Semantics.models_iff.mp $ models_of_provable (T := 𝗜𝚺₁) inferInstance $ def_restrictedGödel;
  simp [models_iff, Theory.RestrictedProvable]

:= by
  by_contra hC;
  obtain ⟨e, _, he⟩ := models_neg_restrictedGödel f (e := e) |>.mp hC;
  apply hC;
  apply iff_true_restrictedGödel_true_restrictedGödel'.mpr;
  apply ArithmeticTheory.soundOnHierarchy T _ _ ?_ T.restrictedGödel'_sigmaOne;
  apply iff_provable_restrictedGödel_provable_restrictedGödel'.mp;
  apply Arithmetic.Bootstrapping.provable_of_standard_proof (T := T) (V := ℕ) (n := e);
  simpa using he;

:= by
  apply iff_provable_restrictedGödel_provable_restrictedGödel'.mpr;
  apply Arithmetic.sigma_one_completeness_iff T.restrictedGödel'_sigmaOne |>.mp;
  apply iff_true_restrictedGödel_true_restrictedGödel'.mp $ true_restrictedGödel f;

:= by
  intro b;
  exact Nat.le_of_not_lt
    $ (imp_not_comm.mp $ (models_restrictedGödel f).mp (true_restrictedGödel f) ⌜b⌝)
    $ proof_of_quote_proof b;

:= by
  apply C_replace ?_ ?_ $ provable_sigma_one_complete (T := T) $ hσ;
  . cl_prover [hσπ];
  . apply T.standardProvability.mono';
    cl_prover [hσπ];

:= by
  rintro ⟨p, hp, hbound⟩ ⟨w, hw, hbound'⟩;
  rcases lt_or_ge p w with h | h <;> grind;

:= by
  apply C_trans ?_ $ contra $ K_left diagonal_fghSentence;
  apply complete.{0};
  intro V _ _;
  simpa [models_iff, Sentence.coe_quote_eq_quote, Theory.fghSentence'] using not_witnessedBefore_of_provedBefore;

:= by
  intro hprov;
  by_cases hw : ∃ w, V ⊧/![w] θ.val;
  . tauto;
  . push Not at hw;
    obtain ⟨p₀, hp₀⟩ := hprov;
    right;
    apply provable_bot_of_provable_of_provable_neg (σ := T.fghSentence θ);
    . use p₀;
    . apply modus_ponens_sentence T (internalize_provability (WeakerThan.pbl refutable_fghSentence_of_provedBefore));
      apply Bootstrapping.Arithmetic.sigma_one_complete T (by simp);
      apply models_iff.mpr;
      simpa using ⟨p₀, hp₀, fun w _ ↦ hw w⟩;

:= by
  rintro (⟨w₀, hw₀⟩ | hbot);
  . by_cases hp : ∃ p < w₀, Proof T p (⌜T.fghSentence θ⌝ : V);
    . obtain ⟨p, -, hp⟩ := hp;
      use p;
    . push Not at hp;
      apply modus_ponens_sentence T (internalize_provability (WeakerThan.pbl (K_right diagonal_fghSentence)));
      apply Bootstrapping.Arithmetic.sigma_one_complete T (by simp);
      simpa [models_iff, Theory.fghSentence'] using ⟨w₀, hw₀, hp⟩;
  . exact provable_of_provable_bot hbot;

:= by
  apply complete.{0};
  intro V _ _;
  simpa [models_iff] using provable_fghSentence_iff;

:= by
  obtain ⟨θ, hwit⟩ := ISigma1.exists_matrix_provable_of_sentence hσ;
  use T.fghSentence' θ;
  apply E_trans provable_fixedpoint'_iff_exs_or_provable_bot;
  apply complete.{0};
  intro V _ _;
  simp [models_iff, show V ⊧/![] σ ↔ ∃ w, V ⊧/![w] θ.val from
    by simpa [Semiformula.eval_ex] using models_iff_of_provable_iff hwit V ![]];

:= by
  obtain ⟨π, heq⟩ := fgh_theorem T hσ;
  use π;
  have heq' : 𝗜𝚺₁ ∪ T.Con ⊢ provabilityPred T π.val 🡘 σ ⋎ provabilityPred T ⊥ := WeakerThan.pbl heq;
  have hcon : 𝗜𝚺₁ ∪ T.Con ⊢ ∼provabilityPred T ⊥ := by_axm (by simp [Theory.consistent]);
  cl_prover [heq', hcon];

:= by
  rintro ⟨τ, hτ⟩;
  apply Entailment.Consistent.not_bot (𝓢 := T);
  have h₁ : T ⊢ fixedpoint (∼τ) 🡘 τ/[⌜fixedpoint (∼τ)⌝] := by simpa using hτ $ fixedpoint “x. ¬!τ x”;;
  have h₂ : T ⊢ fixedpoint (∼τ) 🡘 ∼τ/[⌜fixedpoint (∼τ)⌝] := by simpa using diagonal (T := T) “x. ¬!τ x”;
  cl_prover [h₁, h₂];

:= by
  have := not_exists_tarski_predicate (T := 𝗧𝗔);
  contrapose! this;
  obtain ⟨τ, hτ⟩ := this;
  use τ;
  intro σ;
  apply TA.provable_iff.mpr;
  simpa using hτ σ;

:= by
  apply ComputablePred.computable_of_manyOneReducible (q := λ n : ℕ => Proof T (π₁ n) (π₂ n));
  . use (λ p => Nat.pair p.1 p.2);
    and_intros;
    . exact Primrec₂.natPair.to_comp;
    . simp [←nat_pair_eq];
  . apply computablePred_iff_delta1.mpr;
    definability;

