lemma syntactical_sound {T₀ T : Theory L} {𝔅 : Provability T₀ T}
    (M : Type*) [Nonempty M] [Structure L M] [SoundOn 𝔅 M] [M↓[L] ⊧* T₀] :
    ∀ {σ : Sentence L}, T₀ ⊢ 𝔅 σ → T ⊢ σ

proof:
:= by
  intro σ h;
  apply 𝔅.sound_on;
  apply models_of_provable (L := L) (T := T₀);
  . infer_instance;
  . exact h;

:= by
  have h₁ : T₀ ⊢ 𝔅 (σ ⋏ τ) 🡒 𝔅 σ := bew_distribute_imply $ D1 and₁;
  have h₂ : T₀ ⊢ 𝔅 (σ ⋏ τ) 🡒 𝔅 τ := bew_distribute_imply $ D1 and₂;
  cl_prover [h₁, h₂];

:= by
  have h₁ : T₀ ⊢ 𝔅 σ 🡒 𝔅 (τ 🡒 σ ⋏ τ) := 𝔅.mono $ by cl_prover
  have h₂ : T₀ ⊢ 𝔅 (τ 🡒 σ ⋏ τ) 🡒 𝔅 τ 🡒 𝔅 (σ ⋏ τ) := D2;
  cl_prover [h₁, h₂];

:= by
  have : T₀ ⊢ 𝔅 (∼τ) 🡒 𝔅 (∼σ) := 𝔅.mono $ by cl_prover [h];
  cl_prover [this]

:= by
  intro h;
  have h₁ : T ⊢ 𝔅 (gödel 𝔅) := WeakerThan.pbl $ D1 h;
  have h₂ : T ⊢ (gödel 𝔅) 🡘 ∼𝔅 (gödel 𝔅) := WeakerThan.pbl $ gödel_spec;
  have : T ⊢ ⊥ := by cl_prover [h₁, h₂, h];
  have : ¬Consistent T := not_consistent_iff_inconsistent.mpr <| inconsistent_iff_provable_bot.mpr this;
  contradiction

:= by
  intro h₂;
  have h₁ : T ⊢ (gödel 𝔅) := WeakerThan.pbl $ 𝔅.KR $ by cl_prover [gödel_spec (T₀ := T₀), h₂];
  have : T ⊢ ⊥ := (N_iff_CO.mp $ WeakerThan.pbl $ h₂) ⨀ h₁;
  have : ¬Consistent T := not_consistent_iff_inconsistent.mpr <| inconsistent_iff_provable_bot.mpr this
  contradiction;

:= by
  have := diag (T := T₀) “x. !𝔅.prov x → !σ”
  simpa [kreisel, Provability.pr, Rew.subst_comp_subst, ←TransitiveRewriting.comp_app] using this;

:= by
  have d₁ : T ⊢ 𝔅 (𝐊 σ) 🡒 σ := C_trans (WeakerThan.pbl kreisel_specAux₁) H;
  have d₂ : T ⊢ 𝔅 (𝐊 σ)     := WeakerThan.pbl $ D1 $ WeakerThan.pbl kreisel_specAux₂ ⨀ d₁;
  exact d₁ ⨀ d₂;

:= by
  have h₁ : T₀ ⊢ 𝔅 (𝐊 σ) 🡒 𝔅 σ := kreisel_specAux₁;
  have h₂ : T₀ ⊢ (𝔅 σ 🡒 σ) 🡒 (𝔅 (𝐊 σ) 🡒 σ) := CCC_of_C_left h₁;
  have h₃ : T ⊢ (𝔅 σ 🡒 σ) 🡒 𝐊 σ := WeakerThan.pbl $ C_trans (CCC_of_C_left h₁) kreisel_specAux₂;
  exact C_trans (D2 ⨀ (D1 h₃)) h₁;

:= by
  by_contra hC;
  have : T ⊢ ∼𝔅.con := löb_theorem $ CN_of_CN_right hC;
  have : T ⊬ ∼𝔅.con := con_unrefutable;
  contradiction;

:= by
  by_contra hC;
  have : T ⊬ 𝔅.con 🡒 ∼𝔅 (∼𝔅.con) := formalized_unprovable_not_con;
  have : T ⊢ 𝔅.con 🡒 ∼𝔅 (∼𝔅.con) := C_trans hC
    $ WeakerThan.pbl
    $ K_left $ ENN_of_E
    $ 𝔅.ext
    $ ENN_of_E
    $ WeakerThan.pbl gödel_iff_con
  contradiction;

:= by
  intro hnρ;
  have hρ : T ⊢ 𝐑 := WeakerThan.pbl $ (K_right gödel_spec) ⨀ (Ros hnρ);
  have : ¬Consistent T := not_consistent_iff_inconsistent.mpr $ inconsistent_iff_provable_bot.mpr <|
    (N_iff_CO.mp hnρ) ⨀ hρ;
  contradiction

:= by
  have : T₀ ⊢ ∼𝔅 ⊥ := Ros (N_iff_CO.mpr (by simp));
  exact WeakerThan.pbl $ this;

:= by
  by_contra hC;
  apply Entailment.Consistent.not_bot (𝓢 := T);
  have : T ⊢ ∼(jeroslow 𝔚) := Refutability.sound_on $ (Entailment.iff_of_E $ jeroslow_def') |>.mp hC;
  exact (N_iff_CO.mp this) ⨀ hC;

:= by
  have h₁ : T ⊢ 𝐉 🡒 𝔅 𝐉 := Entailment.WeakerThan.pbl $ 𝔅.formalized_complete_on;
  have h₂ : T ⊢ 𝐉 🡘 𝔚 𝐉 := jeroslow_def';
  cl_prover [h₁, h₂];

:= by
  contrapose! consis;
  replace consis : T ⊢ ∀¹ safe 𝔅 𝔚 := by simpa [flon] using consis;
  have h₁ : T ⊢ ∼(𝔅 𝐉 ⋏ 𝔚 𝐉) := by simpa [safe] using! FirstOrder.Theory.Proof.specialize _ _ ⨀ consis;
  have h₂ : T ⊢ ∼𝐉 := (contra jeroslow_not_safe) ⨀ h₁;
  have h₃ : T ⊢ 𝐉 🡘 𝔚 𝐉 := jeroslow_def';
  have h₄ : T ⊢ 𝔚 𝐉 := R1' h₂;
  have h₅ : T ⊢ 𝔚 𝐉 🡒 𝐉 := by cl_prover [h₃];
  have h₆ : T ⊢ 𝐉 := h₅ ⨀ h₄;
  exact not_consistent_iff_inconsistent.mpr <| inconsistent_iff_provable_bot.mpr $ (N_iff_CO.mp h₂) ⨀ h₆;

:= by
  have : V↓[ℒₒᵣ] ⊧ .univCl (leastNumber φ) :=
    Theory.models (T := LeastNumberScheme C) V (by simpa using mem_LeastNumberScheme_of_mem hφ);
  revert v;
  simpa [models_iff, Semiformula.eval_univCl, leastNumber, Semiformula.eval_substs,
    Matrix.constant_eq_singleton] using this;

statement:
lemma least_number {P : V → Prop}
    (hP : ∃ e : ℕ → V, ∃ φ : ArithmeticSemiformula ℕ 1, C φ ∧ ∀ x, P x ↔ φ.Eval ![x] e)
    {x} (h : P x) : ∃ y, P y ∧ ∀ z < y, ¬P z

proof:
:= by
  rcases hP with ⟨e, φ, Cφ, hφ⟩;
  simpa [← hφ] using leastNumber_eval (V := V) Cφ e ⟨x, (hφ x).mp h⟩;

:=
  LeastNumberScheme.least_number (P := P) (C := Hierarchy Γ m) (by
    classical
    rcases hP with ⟨φ, hp⟩;
    have : Inhabited V := Classical.inhabited_of_nonempty';
    use φ.val.enumerateFVar, (Rew.rewriteMap φ.val.idxOfFVar) ▹ φ.val;
    and_intros;
    . simp;
    . intro x;
      simp [Semiformula.eval_rewriteMap, hp.df.iff]
  ) h

:= by
  have : V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻ := models_of_subtheory ‹V↓[ℒₒᵣ] ⊧* 𝗟 Γ m›;
  have : V↓[ℒₒᵣ] ⊧* 𝗤 := models_of_subtheory this;
  by_contra! hcon;
  obtain ⟨a, ha⟩ := hcon;
  obtain ⟨y, hy, hmin⟩ := least_number Γ m (P := fun x ↦ ¬P x) (by
    apply Arithmetic.HierarchySymbol.Definable.not;
    simpa [SigmaPiDelta.alt_coe];
  ) ha;
  push Not at hmin;
  obtain ⟨z, rfl⟩ := Arithmetic.exists_succ_of_ne_zero $
    show y ≠ 0 by
    rintro rfl;
    contradiction;
  apply hy;
  apply succ;
  apply hmin;
  apply lt_succ_iff_le.mpr;
  apply le_rfl;

:= by
  have : V↓[ℒₒᵣ] ⊧* 𝗣𝗔⁻ := models_of_subtheory ‹V↓[ℒₒᵣ] ⊧* 𝗟 Γ m›;
  suffices V↓[ℒₒᵣ] ⊧* InductionScheme ℒₒᵣ (Hierarchy Γ.alt m) by
    simpa [InductionOnHierarchy, Semantics.ModelsSet.union_iff] using ⟨‹_›, this⟩;
  simp only [InductionScheme];
  apply Semantics.ModelsSet.setOf_iff.mpr;
  rintro _ ⟨φ, hφ, rfl⟩;
  suffices ∀ v : ℕ → V, φ.Eval ![0] v → (∀ x, φ.Eval ![x] v → φ.Eval ![x + 1] v) →
      ∀ x, φ.Eval ![x] v by
    simpa [models_iff, Semiformula.eval_univCl, succInd, Semiformula.eval_substs,
      Matrix.constant_eq_singleton] using this;
  intro v;
