proof:
:= by
  constructor;
  . intro h;
    use m - n - 1;
    omega;
  . rintro ⟨k, rfl⟩;
    apply Nat.lt_add_of_pos_right;
    omega;

:= by
  match a, b with
  | ⊤, ⊤ | ⊤, .some m | .some n, ⊤ => simp;
  | .some n, .some m =>
    intro h;
    apply Option.mem_some_iff.mpr;
    simpa using Option.mem_some_iff.mp h;

:= by
  match a with
  | ⊤       => simp;
  | .some n => apply Option.mem_some_iff.not.mpr; simp;

:= by
  match a with
  | .some 0 => left; rfl;
  | .some (n + 1) => right; use n; rfl;
  | ⊤ => right; use ⊤; rfl;

:= by
  match a, b with
  | ⊤, ⊤ => simp;
  | ⊤, .some n => simp [(show ¬(⊤ : OmegaAddOne) < .some n by tauto)];
  | .some m, ⊤ =>
    simp only [(show .some m < (⊤ : OmegaAddOne) by tauto), true_iff];
    use ⊤;
    rfl;
  | .some m, .some n =>
    apply Iff.trans (show some m < some n ↔ m < n by rfl);
    apply Iff.trans Nat.iff_lt_exists_add_succ;
    constructor;
    . intro h;
      obtain ⟨k, rfl⟩ : ∃ k : ℕ, m + (k + 1) = n := by tauto;
      use k;
      tauto;
    . rintro ⟨c, hc⟩;
      match c with
      | .none => simp at hc;
      | .some c => use c; exact Option.mem_some_iff.mp hc |>.symm;

:= by
  obtain ⟨φ', hφ'⟩ := hasPrenex h;
  exact ⟨φ'.matrix, hφ'⟩

:= by
  obtain ⟨φ', hφ'⟩ := hasPrenex h;
  exact ⟨φ'.sigmaInv.val, φ'.sigmaInv.val_hierarchy, Prenex.provable_iff_sigmaInv hφ'⟩

:= by
  obtain ⟨φ', hφ'⟩ := hasPrenex h;
  exact ⟨φ'.piInv.val, φ'.piInv.val_hierarchy, Prenex.provable_iff_piInv hφ'⟩

